out = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'public', 'i18n')
os.makedirs(out, exist_ok=True)
for lang, blob in T.items():
    vals = [v.strip() for v in blob.replace('\n', '|').split('|')]
    assert len(vals) == len(K), (lang, len(vals), len(K))
    with open(os.path.join(out, lang + '.json'), 'w', encoding='utf-8') as f:
        json.dump(dict(zip(K, vals)), f, ensure_ascii=False, indent=0)
print('wrote', len(T), 'languages,', len(K), 'keys each')
